template <class T, class Container = deque<T> >
class stack {
public:
    bool empty() const;
    int size() const;
    T& top() const;
    void push(const T& val);
    void pop();
private:
    Container contents_;     // container được bọc
};
template <class T, class Container>
void stack<T, Container>::push(const T& val) { contents_.push_back(val); }
template <class T, class Container>
void stack<T, Container>::pop() { contents_.pop_back(); }

