void base_change(int n, int b) {
    char *digits = "0123456789ABCDEF";
    stack<int> stk;
    do {
        stk.push(n % b);
        n /= b;
    } while (n);
    while (!stk.empty()) {
        int u = stk.top();
        stk.pop();
        cout << digits[u];
    }
}
// base_change(3553, 8) in 6741; base_change(255, 16) in FF

int expr_eval(string expr) {
    stack<int> stk;
    for (int i = 0; i < expr.length(); i++) {
        char ch = expr[i];
        if (isdigit(ch)) stk.push(ch - '0');
        else if (isOperator(ch)) {
            int right = stk.top(); stk.pop();   // toán hạng phải ở đỉnh
            int left  = stk.top(); stk.pop();
            stk.push(compute(left, right, ch));
        } else cout << "Expression is not correct" << endl;
    }
    return stk.top();
}

#define ii pair<int, int>
int cnt[1000][1000] = {};
queue<ii> q;
int a, b, c;

void push_and_count(int x, int y, int cur_steps) {
    if ((x < 0) || (y < 0) || (x > a) || (y > b)) return;
    if (!cnt[x][y]) { q.push({x, y}); cnt[x][y] = ++cur_steps; }
}
void water_jug() {
    q.push({a, b}); cnt[a][b] = 1;
    while (!q.empty()) {
        ii u = q.front(); q.pop();
        int x = u.first, y = u.second;
        if (x == c || y == c) { cout << cnt[x][y] - 1; return; }
        push_and_count(x, 0, cnt[x][y]);
        push_and_count(0, y, cnt[x][y]);
        push_and_count(x, b, cnt[x][y]);
        push_and_count(a, y, cnt[x][y]);
        push_and_count(a, x + y - a, cnt[x][y]);
        push_and_count(x + y, 0, cnt[x][y]);
        push_and_count(x + y - b, b, cnt[x][y]);
        push_and_count(0, x + y, cnt[x][y]);
    }
}

